-- Initial snapshot of the five public schemes shown in the frontend.
-- Run database/migrations/0001_create_housing_schemes.sql first.
INSERT INTO housing_schemes (
  slug, name, category, scheme_type, availability, summary, source_name, source_url,
  last_checked_on, agency, eligibility, application_steps, documents, links, display_order
)
VALUES
  ('ppr', 'Program Perumahan Rakyat (PPR)', 'Affordable housing', 'Rent or own', 'unconfirmed', 'A federal housing programme implemented through the National Housing Department and managed by HDC once completed. HDC lists both rental and ownership options.', 'Housing Development Corporation (HDC)', 'https://hdc.sarawak.gov.my/web/subpage/webpage_view/63', DATE '2026-11-06', 'National Housing Department (JPN); managed by HDC once completed.', '["Malaysian citizens residing in Sarawak.","Applicants aged 18 to 65.","Applicants must not own a house or property.","Household income of RM5,000 or below. HDC notes priority for squatters for PPR rental."]'::jsonb, '["The Sarawak public housing service is available online.","Confirm the current PPR application route and availability with HDC before applying."]'::jsonb, '["Copy of applicant’s identity card.","Copy of latest income payslip.","Birth certificate, if applicable."]'::jsonb, '[{"label":"Apply for Public Housing (Service Sarawak)","url":"https://service.sarawak.gov.my/web/web/home/sla_view/0/711/"}]'::jsonb, 1),
  ('rumah-spektra-permata', 'Rumah Spektra Permata (RSP)', 'Affordable housing', 'Home ownership', 'unconfirmed', 'A Sarawak Government housing programme intended to help low- and middle-income families own a home. HDC describes eligibility and project conditions on its official page.', 'Housing Development Corporation (HDC)', 'https://hdc.sarawak.gov.my/web/subpage/webpage_view/127', DATE '2026-11-06', 'Sarawak Government; administered by the Housing Development Corporation (HDC).', '["HDC’s scheme page lists these conditions: applicants are lot holders allocated by the Land and Survey Department; applicants are aged 18–65; they do not own a house or land; and they are married or a single parent. The page lists household income between RM1,500 and RM6,000.","HDC marks the scheme information as updated 23 July 2025. Confirm current terms with HDC before applying."]'::jsonb, '["Applications are tied to specific housing projects and registration periods.","Check HDC’s current announcements or contact HDC to confirm whether registration is open for a project relevant to you."]'::jsonb, '[]'::jsonb, '[{"label":"HDC announcements","url":"https://hdc.sarawak.gov.my/web/subpage/announcement_list/"}]'::jsonb, 2),
  ('housing-deposit-assistance', 'Housing Deposit Assistance Scheme (HDAS)', 'Financial assistance', 'Deposit assistance', 'unconfirmed', 'Sarawak Government assistance for eligible first-home buyers, and certain landowners building on land under designated village schemes. Check HDC for current conditions.', 'Housing Development Corporation (HDC)', 'https://hdc.sarawak.gov.my/web/subpage/webpage_view/163', DATE '2026-11-06', 'Sarawak Government; contact MUTIARA for application enquiries.', '["HDC describes the scheme for Sarawakians in the B40 and M40 groups buying a first home, with deposit assistance of 10% up to RM10,000.","HDC also describes support for certain landowners building on land allocated under the Village Expansion Scheme (SPK) or Resettlement Scheme (SPS). Confirm all current conditions with HDC or MUTIARA."]'::jsonb, '["Contact MUTIARA at 082-313035 or apply at a MUTIARA office, as directed by HDC.","Confirm the current process and required documents before preparing an application."]'::jsonb, '[]'::jsonb, '[{"label":"Contact and application information (HDC)","url":"https://hdc.sarawak.gov.my/web/subpage/webpage_view/163"}]'::jsonb, 3),
  ('sras-rental-assistance', 'Sarawak Rental Assistance Scheme (SRAS)', 'Rental assistance', 'Rental support', 'unconfirmed', 'Sarawak Government rental support for eligible tenants. The 2026 programme update includes Miri among the covered districts; check HDC for current eligibility and application details.', 'Housing Development Corporation (HDC)', 'https://hdc.sarawak.gov.my/web/subpage/webpage_view/139', DATE '2026-11-06', 'Sarawak Government; administered by the Housing Development Corporation (HDC).', '["Miri is listed among the covered districts in the 2026 programme update.","The update reports a monthly household income limit raised to RM5,504 and assistance extended to up to 48 months. Confirm how the current criteria apply to your household with HDC."]'::jsonb, '["Check the HDC SRAS page for the current application process and whether applications are open.","The application portal is linked from HDC’s official SRAS page."]'::jsonb, '[]'::jsonb, '[{"label":"SRAS application portal (linked by HDC)","url":"https://apply-sras.ireka.my/"},{"label":"2026 SRAS update and Miri coverage (UKAS)","url":"https://ukas.sarawak.gov.my/web/subpage/news_view/40777"}]'::jsonb, 4),
  ('pprms-home-repair', 'Program Penambahbaikan Rumah Rakyat Miskin Sarawak (PPRMS)', 'Home repair assistance', 'Home repairs', 'unconfirmed', 'Sarawak assistance to improve unsafe or deteriorated homes for households in need. Official reporting documents PPRMS repairs in Miri, including Pujut, Krokop and Piasau.', 'Unit Komunikasi Awam Sarawak (UKAS)', 'https://ukas.sarawak.gov.my/web/subpage/news_view/50299', DATE '2026-11-06', 'Sarawak Government, coordinated locally through constituency service centres and community representatives.', '["Local UKAS reporting describes support for low-income and families in need, with priority for older people, people with disabilities, and single-parent households.","Eligibility is assessed locally. Contact your constituency service centre to confirm the current criteria and whether support is available in your area."]'::jsonb, '["For Miri, ask your local constituency service centre about assessment and application steps.","UKAS reporting describes Pujut-area repairs coordinated through the Pujut People’s Service Centre."]'::jsonb, '[]'::jsonb, '[{"label":"PPRMS repairs in Miri (UKAS)","url":"https://ukas.sarawak.gov.my/web/subpage/news_view/50299"}]'::jsonb, 5)
ON CONFLICT (slug) DO NOTHING;
